import { useCallback } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { AppDispatch } from '../store';
import {
  initializeQuiz,
  completeStep,
  submitQuiz,
  setCurrentStepIndex,
  resetQuiz,
  selectCurrentQuizId,
  selectParticipant,
  selectSteps,
  selectCompletedSteps,
  selectCurrentStepIndex,
  selectCurrentStep,
  selectLoading,
  selectError,
  selectQuiz
} from '../store/features/quiz/quizSlice';

export const useQuiz = () => {
  const dispatch = useDispatch<AppDispatch>();

  const currentQuizId = useSelector(selectCurrentQuizId);
  const quiz = useSelector(selectQuiz);
  const participant = useSelector(selectParticipant);
  const steps = useSelector(selectSteps);
  const completedSteps = useSelector(selectCompletedSteps);
  const currentStepIndex = useSelector(selectCurrentStepIndex);
  const currentStep = useSelector(selectCurrentStep);
  const loading = useSelector(selectLoading);
  const error = useSelector(selectError);

  const initialize = useCallback(
    (quizId: string) => dispatch(initializeQuiz(quizId)),
    []
  );

  const complete = useCallback(
    (params: { stepNumber: number; answerId?: number }) =>
      dispatch(completeStep(params)),
    [dispatch]
  );

  const submit = useCallback(
    (params: { email: string }) =>
      dispatch(submitQuiz(params)),
    [dispatch]
  );

  const setStep = useCallback(
    (index: number) => dispatch(setCurrentStepIndex(index)),
    [dispatch]
  );

  const reset = useCallback(
    () => dispatch(resetQuiz()),
    [dispatch]
  );

  const isLastStep = currentStepIndex === steps.length - 1;
  const progress = steps.length > 0 ? (currentStepIndex + 1) / steps.length : 0;

  return {
    // State
    currentQuizId,
    quiz,
    participant,
    steps,
    completedSteps,
    currentStepIndex,
    currentStep,
    loading,
    error,
    isLastStep,
    progress,

    // Actions
    initialize,
    complete,
    submit,
    setStep,
    reset
  };
};

export const useQuizStep = (stepIndex: number) => {
  const steps = useSelector(selectSteps);
  const completedSteps = useSelector(selectCompletedSteps);

  const step = steps[stepIndex];
  const isCompleted = completedSteps.some(
    (completedStep: { stepNumber: number; completedAt: string }) =>
      completedStep.stepNumber === stepIndex + 1
  );

  return {
    step,
    isCompleted
  };
};

export const useQuizProgress = () => {
  const steps = useSelector(selectSteps);
  const completedSteps = useSelector(selectCompletedSteps);
  const currentStepIndex = useSelector(selectCurrentStepIndex);

  const totalSteps = steps.length;
  const completedCount = completedSteps.length;
  const progress = totalSteps > 0 ? completedCount / totalSteps : 0;
  const isComplete = completedCount === totalSteps;

  return {
    totalSteps,
    completedCount,
    currentStepIndex,
    progress,
    isComplete
  };
};
