import React, { useEffect, useMemo } from 'react';
import _, { find, map, max, reduce, set } from 'lodash';
import { useTranslation } from 'react-i18next';
import { useQuiz } from '../../../hooks/useQuiz';
import { useAnalytics } from '../../../hooks/useAnalytics';
import { OrbitalWheel } from '../../common/OrbitalWheel/OrbitalWheel';
import { WelcomeToVitawell, Question, Submit } from './components';
import { getConfigValue } from '../../../api/config';
import { Completion } from './components/Completion';
import { CATEGORY_CONFIG } from '../../../constants/categoryConfig';
import { IQuestion, IQuiz, IStep } from '@/models/interfaces/quiz';
import { IQuizParticipant } from '@/models';

export interface QuizStepComponentProps {
  step: IStep;
  loading?: boolean;
  onComplete: (answerId?: string | number) => void;
}

const quizStepToComponentMap: Record<string, React.FC<QuizStepComponentProps>> = {
  WelcomeToVitawell: WelcomeToVitawell,
  Question: Question,
  Submit: Submit,
  Completion: Completion,
};

const QuizContainer: React.FC = () => {
  const { t } = useTranslation();
  const {
    initialize,
    currentStep,
    loading,
    error,
    complete,
    submit,
    currentQuizId,
    setStep,
    currentStepIndex,
    quiz,
    participant
  } = useQuiz()

  const { trackStepSubmitted, trackSubmitEmail } = useAnalytics();

  useEffect(() => {
    const quizId = getConfigValue('quizId', '');

    if (quizId) {
      initialize(quizId);
    }
  }, []);

  if (loading && !currentStep) {
    return (
      <div className="flex justify-center items-center h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#46bdc6]"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex justify-center items-center h-screen">
        <div className="text-red-500 text-center">
          <p className="text-xl font-semibold">{t('An error has occurred')}</p>
          <p>{t(error)}</p>
        </div>
      </div>
    );
  }

  if (!currentStep || !currentQuizId) {
    return null;
  }

  const handleStepComplete = async (result?: string | number) => {
    try {
      if (currentStep.componentName === 'Submit' && typeof result === 'string') {
        // For submit step, complete the step and submit the quiz
        await complete({
          stepNumber: currentStepIndex + 1
        });

        trackSubmitEmail(result)

        await submit({
          email: result
        });
      } else {
        // For other steps, just complete the step
        await complete({
          stepNumber: currentStepIndex + 1,
          answerId: typeof result === 'string' ? parseInt(result) : result // Convert string ID to number if needed
        });
      }
      trackStepSubmitted(currentStep.componentName);
      setStep(currentStepIndex + 1);
    } catch (error) {
      console.error(t('Failed to complete step:'), error);
    }
  };

  const renderCurrentStep = () => {
    const Component = quizStepToComponentMap[currentStep.componentName];

    if (Component) {
      return (
        <Component
          step={currentStep}
          onComplete={handleStepComplete}
          loading={loading}
        />
      );
    }

    return (
      <div className="text-center text-red-500">
        {t('Unknown component type:')} {currentStep.componentName}
      </div>
    );
  };

  const baseSize = _.clamp(window.innerHeight * 0.4, 200, 600);

  const calculateTopicDistribution = (
    participant: IQuizParticipant | null,
    quiz: IQuiz | null
  ): Record<string, number> => {
    type TotalDistribution = Record<string, { total: number, current: number }>

    const totalCurrent = quiz?.steps.reduce((acum: TotalDistribution, step, index) => {
      const { question } = step
      if (!question || !question.answers) return acum

      const participantAnswerId = participant?.completedSteps[index]?.answerId
      const answer = find(question.answers, { id: participantAnswerId })

      const prev = acum[question.topic] ?? { total: 0, current: 0 }

      prev.total = (prev.total ?? 0) + Math.max(...map(question.answers, 'weight'))
      prev.current = (prev.current ?? 0) + (answer?.weight ?? 0)

      acum[question.topic] = prev

      return acum
    }, {})

    type TopicDistribution = Record<string, number>

    return reduce<TotalDistribution, TopicDistribution>(totalCurrent, (prev: TopicDistribution, value, key) => {
      prev[key] = value.current / value.total
      return prev
    }, {})
  };

  const topicDistribution = calculateTopicDistribution(participant, quiz)

  return (
    <div className="min-h-screen flex flex-col">
      <div className="flex items-center justify-center" style={{ height: baseSize }}>
        <OrbitalWheel
          topicDistribution={topicDistribution}
          animationDuration={300}
          baseSize={baseSize}
        />
      </div>

      <div className="flex items-center justify-center p-4 max-w-[500px] mx-auto">
        {renderCurrentStep()}
      </div>
    </div>
  );
};

export default React.memo(QuizContainer);