interface ApiConfig {
  baseURL: string;
  defaultHeaders: Record<string, string>;
}

export const API_CONFIG: ApiConfig = {
  baseURL: import.meta.env.VITE_API_URL || 'http://localhost:1337',
  defaultHeaders: {
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  }
};

export const STORAGE_KEYS = {
  PARTICIPANT: 'vitawell_participant',
  QUIZ_ID: 'vitawell_quiz_id',
  LANGUAGE: 'vitawell_language'
};

export const DEFAULT_LANGUAGE = 'en';

export const getUrlParam = (param: string): string | null => {
  const urlParams = new URLSearchParams(window.location.search);
  return urlParams.get(param);
};

export const getConfigValue = (key: string, defaultValue: string = ''): string => {
  // First check URL parameters
  const urlValue = getUrlParam(key);
  if (urlValue) return urlValue;

  // Then check environment variables
  const envKey = `VITE_${key.toUpperCase()}`;
  const envValue = import.meta.env[envKey];
  if (envValue) return envValue;

  // Finally return default value
  return defaultValue;
};
