import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { quizService, participantService } from '@/api/services';
import { IQuiz, IQuizParticipant } from '@/models/interfaces';
import { getConfigValue, STORAGE_KEYS } from '@/api/config';
import { differenceBy, merge } from 'lodash';

// Define the state interface
interface QuizState {
  currentQuizId: string | null;
  quiz: IQuiz | null;
  participant: IQuizParticipant | null;
  steps: any[];
  completedSteps: any[];
  currentStepIndex: number;
  loading: boolean;
  error: string | null;
}

const initialState: QuizState = {
  currentQuizId: null,
  quiz: null,
  participant: null,
  steps: [],
  completedSteps: [],
  currentStepIndex: 0,
  loading: false,
  error: null,
};

// Create async thunks for API calls
export const initializeQuiz = createAsyncThunk(
  'quiz/initialize',
  async (quizId: string, { rejectWithValue }) => {
    try {
      const locale = getConfigValue('locale', 'en');
      const quiz = await quizService.getQuiz({ uuid: quizId, locale });
      const participant = await participantService.getOrCreateParticipant(quizId);

      return { quiz, participant };
    } catch (error: any) {
      return rejectWithValue(error.message);
    }
  }
);

export const completeStep = createAsyncThunk(
  'quiz/completeStep',
  async ({ stepNumber, answerId }: { stepNumber: number; answerId?: number },
    { getState, rejectWithValue }) => {
    try {
      const state = getState() as { quiz: QuizState };
      if (!state.quiz.participant || !state.quiz.currentQuizId) {
        throw new Error('Participant or quiz not initialized');
      }

      let updatedParticipant = state.quiz.participant;
      const currentStep = state.quiz.steps[stepNumber - 1]

      // Update progress
      updatedParticipant = await participantService.updateProgress(
        state.quiz.currentQuizId,
        state.quiz.participant.uuid,
        stepNumber,
        currentStep?.question?.id,
        answerId
      );

      return updatedParticipant;
    } catch (error: any) {
      return rejectWithValue(error.message);
    }
  }
);

export const submitQuiz = createAsyncThunk(
  'quiz/submit',
  async ({ email }: { email: string }, { getState, rejectWithValue }) => {
    try {
      const state = getState() as { quiz: QuizState };
      if (!state.quiz.participant || !state.quiz.currentQuizId) {
        throw new Error('Participant or quiz not initialized');
      }

      const updatedParticipant = await participantService.updateParticipantEmail(
        state.quiz.currentQuizId,
        state.quiz.participant.uuid,
        email
      );

      return updatedParticipant;
    } catch (error: any) {
      return rejectWithValue(error.message);
    }
  }
);

// Create the quiz slice
const quizSlice = createSlice({
  name: 'quiz',
  initialState,
  reducers: {
    setCurrentStepIndex: (state, action) => {
      state.currentStepIndex = action.payload;
    },
    resetQuiz: () => initialState,
  },
  extraReducers: (builder) => {
    builder
      // Initialize Quiz
      .addCase(initializeQuiz.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(initializeQuiz.fulfilled, (state, action) => {
        state.loading = false;
        state.quiz = action.payload.quiz;
        state.participant = merge(state.participant, action.payload.participant);
        state.steps = action.payload.quiz.steps;
        state.currentQuizId = action.payload.quiz.uuid;
        state.currentStepIndex = action.payload.participant.currentStep - 1;
        state.completedSteps = action.payload.participant.completedSteps;
      })
      .addCase(initializeQuiz.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // Complete Step
      .addCase(completeStep.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(completeStep.fulfilled, (state, action) => {
        state.loading = false;
        state.participant = merge(state.participant, action.payload);
        state.completedSteps = action.payload.completedSteps;
      })
      .addCase(completeStep.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })
      // Submit Quiz
      .addCase(submitQuiz.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(submitQuiz.fulfilled, (state, action) => {
        state.loading = false;
        state.participant = merge(state.participant, action.payload);
      })
      .addCase(submitQuiz.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      });
  },
});

// Export actions and reducer
export const { setCurrentStepIndex, resetQuiz } = quizSlice.actions;

// Selectors
export const selectCurrentQuizId = (state: { quiz: QuizState }) => state.quiz.currentQuizId;
export const selectQuiz = (state: { quiz: QuizState }) => state.quiz.quiz;
export const selectParticipant = (state: { quiz: QuizState }) => state.quiz.participant;
export const selectSteps = (state: { quiz: QuizState }) => state.quiz.steps;
export const selectCompletedSteps = (state: { quiz: QuizState }) => state.quiz.completedSteps;
export const selectCurrentStepIndex = (state: { quiz: QuizState }) => state.quiz.currentStepIndex;
export const selectCurrentStep = (state: { quiz: QuizState }) => state.quiz.steps[state.quiz.currentStepIndex];
export const selectLoading = (state: { quiz: QuizState }) => state.quiz.loading;
export const selectError = (state: { quiz: QuizState }) => state.quiz.error;

export default quizSlice.reducer;