import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { AlertCircle, Send } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { Input } from '@/components/ui/input';
import { cn } from '@/lib/utils';
import { QuizStepComponentProps } from '../QuizContainer';
import { count } from 'console';

export const Submit: React.FC<QuizStepComponentProps> = ({
  step,
  onComplete,
  loading = false
}) => {
  const { t } = useTranslation();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [validation, setValidation] = useState<{ isValid: boolean, error: string | null}>({ isValid: false, error: null });

  useEffect(() => {
    if (email) {
      const isValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      setValidation({
        isValid,
        error: isValid ? null : 'email.errors.invalid'
      });
    } else {
      setValidation({
        isValid: false,
        error: touched ? 'email.errors.required' : null
      });
    }
  }, [email, touched]);

  const handleSubmit = async () => {
    if (validation.isValid && !loading) {
      onComplete(email);
    } else {
      setTouched(true);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && validation.isValid && !loading) {
      handleSubmit();
    }
  };

  const categories = useMemo(() => {
    return Math.floor(Math.random() * 16) + 11;
  }, []);
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      className="w-full px"
    >
      <h2 className="text-xl sm:text-2xl md:text-3xl font-bold text-center text-gray-800 mb-6 sm:mb-8">
        {t('Get {{categories}} unique insights and tips to improve your life balance wheel!', { categories })}
      </h2>

      <div className="space-y-2 min-h-[120px] sm:min-h-[160px]">
        <div className="relative">
          <Input
            type="email"
            placeholder={t('your@email.com')}
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            onBlur={() => setTouched(true)}
            onKeyPress={handleKeyPress}
            disabled={loading}
            className={cn(
              'w-full mb-1 pl-10 sm:pl-12 py-4 sm:py-6 text-base sm:text-lg rounded-xl sm:rounded-2xl border-2 transition-all duration-300 placeholder:text-teal-300 shadow-sm',
              !touched || validation.isValid
                ? 'border-teal-400 hover:border-teal-500 focus:border-teal-500'
                : 'border-red-400 hover:border-red-500 focus:border-red-500',
              loading && 'opacity-50 cursor-not-allowed',
            )}
          />
          <Send
            className={cn(
              'absolute left-3 sm:left-4 top-1/2 -translate-y-1/2 h-4 w-4 sm:h-5 sm:w-5 transition-colors duration-300',
              !touched || validation.isValid ? 'text-teal-400' : 'text-red-400',
              loading && 'opacity-50',
            )}
          />
        </div>

        {/* Error container */}
        <div className="h-6">
          <AnimatePresence mode="wait">
            {(touched && validation.error) && (
              <motion.div
                initial={{ opacity: 0, y: -5 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -5 }}
                transition={{ duration: 0.2 }}
                className="flex items-center gap-2 text-red-500 text-sm px-2"
                id="email-error"
              >
                <AlertCircle className="h-4 w-4" />
                <span>{t('Please enter a valid email address')}</span>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Button container */}
        <AnimatePresence mode="wait">
          {validation.isValid && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.3, ease: 'easeInOut' }}
            >
              <motion.button
                initial={{ y: 20 }}
                animate={{ y: 0 }}
                exit={{ y: 20 }}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                className={cn(
                  'w-full bg-gradient-to-r from-teal-400 to-blue-500 text-white py-4 rounded-xl font-bold text-lg md:text-xl transition-all duration-300 shadow-md hover:shadow-lg',
                  loading && 'opacity-50 cursor-not-allowed',
                )}
                onClick={handleSubmit}
                disabled={loading}
              >
                {loading ? (
                  <div className="flex items-center justify-center gap-2">
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white" />
                    {t('Submitting...')}
                  </div>
                ) : (
                  t('Send my recommendations')
                )}
              </motion.button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  );
};

export default Submit;