import React from 'react';
import { useTranslation } from 'react-i18next';
import { QuizStepComponentProps } from '../QuizContainer';

export const Question: React.FC<QuizStepComponentProps> = ({
  step,
  onComplete,
  loading = false
}) => {
  const { t } = useTranslation();

  if (!step.question) {
    return (
      <div className="text-center text-red-500">
        {t('Question data not found')}
      </div>
    );
  }

  return (
    <div className="w-full px-1 max-w-lg mx-auto">
      <div className="relative mb-2 pb-4px">
        <h2 className="text-2xl md:text-3xl font-bold text-center text-gray-800">
          {step.question.content}
        </h2>
      </div>

      <div className="grid gap-2 min-h-[800px]:gap-4 align-middle mx-auto">
        {step.question.answers.map((answer) => (
          <button
            key={answer.id}
            onClick={() => onComplete(answer.id)}
            disabled={loading}
            className="w-[100%] mx-auto bg-white border-2 border-[#46bdc6] text-gray-700 py-4 px-2 rounded-xl
              font-medium text-lg transition-all duration-300 hover:bg-[#46bdc6]/5
              hover:border-[#46bdc6] hover:text-[#46bdc6] shadow-md hover:shadow-lg flex items-center
              justify-center gap-3"
          >
            <span>{answer.text}</span>
          </button>
        ))}
      </div>
    </div>
  );
};