import React, { useEffect, useRef, useState } from 'react';
import { CATEGORY_CONFIG } from '../../../constants/categoryConfig';

interface OrbitalWheelProps {
  topicDistribution: Record<string, number>;
  baseSize?: number;
  animationDuration?: number;
  iconOffset?: number;
}

export const OrbitalWheel: React.FC<OrbitalWheelProps> = ({
  topicDistribution,
  baseSize = 240,
  animationDuration = 300
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState(baseSize);

  // Add safety margin for mobile devices
  // const safetyMargin = 32; // Additional padding for mobile
  const effectiveSize = size;

  useEffect(() => {
    const updateSize = () => {
      if (containerRef.current) {
        const containerWidth = containerRef.current.clientWidth;
        const containerHeight = containerRef.current.clientHeight;
        const minDimension = Math.min(containerWidth, containerHeight, baseSize);
        setSize(minDimension);
      }
    };

    updateSize();

    const resizeObserver = new ResizeObserver(updateSize);
    if (containerRef.current) {
      resizeObserver.observe(containerRef.current);
    }

    return () => {
      if (containerRef.current) {
        resizeObserver.unobserve(containerRef.current);
      }
    };
  }, [baseSize]);

  const config = Object.entries(topicDistribution).reduce((acc, [topic, weight]) => {
    acc[topic] = { value: weight };
    return acc;
  }, {} as Record<string, { value: number }>);

  const topicKeys = Object.keys(topicDistribution);

  const iconOffset = 30
  const iconSize = size * 0.07;

  const centerX = size / 2;
  const centerY = size / 2;
  const baseRadius = effectiveSize * 0.05;

  const maxRadius = effectiveSize / 2 - iconOffset - iconSize * 2;

  const describeArc = (startAngle: number, endAngle: number, value: number): string => {
    const start = startAngle * (Math.PI / 180);
    const end = endAngle * (Math.PI / 180);
    const radius = baseRadius + ((maxRadius - baseRadius) * value);

    const startX = centerX + Math.cos(start) * radius;
    const startY = centerY + Math.sin(start) * radius;
    const endX = centerX + Math.cos(end) * radius;
    const endY = centerY + Math.sin(end) * radius;
    const innerStartX = centerX + Math.cos(start) * baseRadius;
    const innerStartY = centerY + Math.sin(start) * baseRadius;
    const innerEndX = centerX + Math.cos(end) * baseRadius;
    const innerEndY = centerY + Math.sin(end) * baseRadius;

    const largeArcFlag = end - start <= Math.PI ? '0' : '1';

    return [
      `M ${innerStartX} ${innerStartY}`,
      `L ${startX} ${startY}`,
      `A ${radius} ${radius} 0 ${largeArcFlag} 1 ${endX} ${endY}`,
      `L ${innerEndX} ${innerEndY}`,
      `A ${baseRadius} ${baseRadius} 0 ${largeArcFlag} 0 ${innerStartX} ${innerStartY}`,
      'Z'
    ].join(' ');
  };

  const getIconPosition = (index: number, value: number) => {
    const segmentAngle = 360 / topicKeys.length;
    const midAngle = ((index * segmentAngle) + (segmentAngle / 2) - 90) * (Math.PI / 180);
    const radius = baseRadius + ((maxRadius - baseRadius) * value);

    const offsetRadius = radius + iconOffset + iconSize / 2;

    return {
      x: centerX + Math.cos(midAngle) * offsetRadius,
      y: centerY + Math.sin(midAngle) * offsetRadius
    };
  };

  return (
    <div
      ref={containerRef}
      className="relative w-full aspect-square max-w-full"
      style={{ maxWidth: `${baseSize}px` }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${size} ${size}`}
        className="max-w-full"
        preserveAspectRatio="xMidYMid meet"
      >
        <defs>
          <filter id="glow">
            <feGaussianBlur stdDeviation="2" result="coloredBlur"/>
            <feMerge>
              <feMergeNode in="coloredBlur"/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
        </defs>

        {topicKeys.map((key, i) => {
          const segmentAngle = 360 / topicKeys.length;
          const startAngle = (i * segmentAngle) - 90;
          const endAngle = ((i + 1) * segmentAngle) - 90;
          const value = Math.max(config[key]?.value || 0, 0.1);
          const iconPos = getIconPosition(i, value);
          const categoryConfig = CATEGORY_CONFIG[key];

          // Scale icon and text size based on container size
          const textScale = iconSize

          return (
            <g key={key} className="transition-all" style={{ transitionDuration: `${animationDuration}ms` }}>
              <path
                d={describeArc(startAngle, endAngle, value)}
                fill={categoryConfig?.color || '#ccc'}
                opacity={0.18}
              />
              <g
                transform={`translate(${iconPos.x}, ${iconPos.y})`}
                className="transition-all"
                style={{ transitionDuration: `${animationDuration}ms` }}
              >
                <circle
                  r={iconSize}
                  fill={categoryConfig?.color || '#ccc'}
                  className="cursor-pointer"
                />
                <text
                  textAnchor="middle"
                  dominantBaseline="central"
                  fontSize={textScale}
                  className="pointer-events-none select-none"
                >
                  {categoryConfig?.icon || '❓'}
                </text>
              </g>
            </g>
          );
        })}

        <circle
          cx={centerX}
          cy={centerY}
          r={size * 0.02}
          fill="#46bdc6"
          className="animate-pulse"
          filter="url(#glow)"
        />
      </svg>
    </div>
  );
};